// Secret check and field validation. Keeps the uploaded binary as `video`.
const item = $input.first();
const headers = item.json.headers || {};
const body = item.json.body || {};

// Constant-time compare: walks the longer string whatever the input, and folds
// the length difference into the result.
const given = String(headers['x-openshorts-secret'] || '');
const expected = String($env.OPENSHORTS_WEBHOOK_SECRET || '');
let diff = given.length ^ expected.length;
for (let i = 0; i < Math.max(given.length, expected.length); i++) {
  diff |= (given.charCodeAt(i) || 0) ^ (expected.charCodeAt(i) || 0);
}
if (!expected || diff !== 0) {
  return [{ json: { route: 'unauthorized', error: 'unauthorized' } }];
}

const invalid = (error) => [{ json: { route: 'invalid', error } }];
const video = item.binary && item.binary.video;
if (!video) return invalid('missing video file');

const title = String(body.title || '').trim();
const description = String(body.description || '');
const privacy = String(body.privacy || '').trim();
const jobId = String(body.job_id || '').trim();
const clipIndex = String(body.clip_index ?? '').trim();
const tags = String(body.tags || '').split(',').map((t) => t.trim()).filter(Boolean);

if (!title) return invalid('title is empty');
if (title.length > 100) return invalid('title over 100 characters');
if (description.length > 5000) return invalid('description over 5000 characters');
if (!['private', 'unlisted', 'public'].includes(privacy)) return invalid('privacy must be private, unlisted or public');
if (!/^[A-Za-z0-9_-]{1,128}$/.test(jobId)) return invalid('invalid job_id');
if (!/^\d{1,4}$/.test(clipIndex)) return invalid('invalid clip_index');

return [{
  json: {
    route: 'ok',
    title,
    description,
    privacy,
    // null, not '', so the YouTube node sends no tags at all when there are none.
    tags: tags.length ? tags.join(',') : null,
    filename: `${jobId}_${clipIndex}.mp4`,
  },
  binary: { video },
}];

// The Drive node returns metadata only: hand the YouTube node the clip again.
const drive = $input.first().json;
const id = drive.id;
return [{
  json: {
    ...$('Check secret and validate').first().json,
    drive_file_id: id,
    drive_link: drive.webViewLink || `https://drive.google.com/file/d/${id}/view`,
  },
  binary: $('Check secret and validate').first().binary,
}];
